children = {
    "A": ["B", "C"],
    "B": ["D", "E"],
    "C": [], "D": [], "E": []
}

def height(node):
    if node is None:
        return -1
    longest_child = -1
    for child in children[node]:
        longest_child = max(longest_child, height(child))
    return 1 + longest_child

print(height("A"))
print(height("B"))
print(height("E"))
print(height(None))
